CREATE TABLE IF NOT EXISTS channel_inbox_events (
  id TEXT PRIMARY KEY,
  source_key TEXT UNIQUE,
  space_id TEXT,
  connection_key TEXT,
  import_key TEXT,
  adapter TEXT,
  adapter_version INTEGER,
  provider_event_id TEXT,
  subject TEXT,
  payload_fingerprint TEXT,
  sequence INTEGER,
  occurred_at TEXT,
  received_at TEXT,
  processed INTEGER CHECK(processed IN (0, 1)),
  effect TEXT CHECK(effect IN ('pending', 'applied', 'ignored', 'quarantined', 'duplicate')),
  effect_reason TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
) STRICT;
